const ICON_DATA: Record<string, string> = {
  "Safari": "",
  "Chrome": "",
  "Edge": "",
  "Firefox": "",
  "Opera": "",
  "Brave": "",
  "Vivaldi": "",
  "Arc": "",
  "DuckDuckGo": "",
  "Samsung Internet": "",
  "Tor Browser": "",
}

const cachedImages = new Map<string, UIImage | null>()

export function browserIcon(name: string): UIImage | null {
  const data = ICON_DATA[name]
  if (!data) return null
  if (!cachedImages.has(name)) cachedImages.set(name, UIImage.fromBase64String(data))
  return cachedImages.get(name) ?? null
}
